    about_intro: "مرحباً بكم في Brother Sharm Tours، بوابتكم المثالية لاكتشاف الجمال الخلاب والمغامرات المثيرة في شرم الشيخ.",
    about_who_title: "من نحن",
    about_who_body: "نحن أخوان نفخر بأن شرم الشيخ هي موطننا. وبفضل خبرة ميدانية وشغف عميق بصناعة السياحة والسفر يعود إلى عام 2009، بُنيت رحلتنا على سنوات من الخبرة. وما ألهمنا حقاً لإطلاق هذه المنصة هو التشجيع المستمر من أصدقائنا وعملائنا الذين جربوا رحلاتنا بأنفسهم. نحن نعشق المناظر الصحراوية ومياه البحر الأحمر الصافية والحياة البحرية النابضة، ورسالتنا هي انتقاء أفضل التجارب في هذه الجنة وربطكم بها من خلال التعاون مع أفضل المشغلين المحليين.",
    about_vision_title: "رؤيتنا",
    about_vision_body: "نؤمن بأن كل مسافر يستحق تجربة شخصية وآمنة لا تُنسى. وما يميزنا — وما نهتم به أكثر — هو الثقة والمصداقية والعلاقات الإنسانية الصادقة، وليس مجرد إتمام عملية بيع. وبدلاً من الجولات النمطية، ننتقي وننظّم مغامرات مُصممة لتصنع ذكريات تدوم مدى الحياة — من رحلات السفاري الصحراوية بالدراجات الرباعية إلى جولات السنوركلينج والغوص الهادئة.",
