    // Added by scripts/i18n-inject.mjs
    about_heading: "Über uns",
    about_welcome_title: "Willkommen bei Brother Sharm Tours",
    about_intro: "Willkommen bei Brother Sharm Tours, Ihrem Tor zur atemberaubenden Schönheit und den aufregenden Abenteuern von Sharm El-Sheikh.",
    about_who_title: "Wer wir sind",
    about_who_body: "Wir sind zwei Brüder, für die Sharm El-Sheikh Heimat ist. Gestützt auf praktische Erfahrung und eine tiefe Leidenschaft für Tourismus und Reisen seit 2009 beruht unser Weg auf jahrelanger Expertise. Zum Start dieser Plattform inspiriert hat uns vor allem der stetige Zuspruch von Freunden und Gästen, die unsere Touren selbst erlebt haben. Wir lieben die Wüstenlandschaften, das kristallklare Wasser des Roten Meeres und die lebendige Unterwasserwelt. Unsere Mission: die allerbesten Erlebnisse dieses Paradieses für Sie auszuwählen und Sie mit ihnen zu verbinden — in Zusammenarbeit mit erstklassigen lokalen Anbietern.",
    about_vision_title: "Unsere Vision",
    about_vision_body: "Wir glauben, dass jeder Reisende ein persönliches, sicheres und unvergessliches Erlebnis verdient. Was uns auszeichnet — und was uns am wichtigsten ist — sind Vertrauen, Glaubwürdigkeit und echte Beziehungen, nicht der schnelle Verkauf. Statt Standardtouren wählen und organisieren wir Abenteuer, die Erinnerungen fürs Leben schaffen — von rasanten Quad-Safaris in der Wüste bis zu ruhigen Schnorchel- und Tauchausflügen.",
    about_why_title: "Warum mit uns reisen?",
    about_local_title: "Lokale Expertise",
    about_local_body: "Wir kennen jedes versteckte Juwel, jede beste Route und jeden Top-Spot in Sharm — gestützt auf unsere Erfahrung seit 2009, um Sie richtig zu führen.",
    about_safety_title: "Sicherheit zuerst",
    about_safety_body: "Wir arbeiten sorgfältig mit den vertrauenswürdigsten, zertifizierten Anbietern in Sharm zusammen, damit Ausrüstung, Boote und Fahrzeuge höchsten Sicherheitsstandards entsprechen — für Ihre völlige Sorgenfreiheit.",
    about_care_title: "Persönliche Betreuung & Glaubwürdigkeit",
    about_care_body: "Als familiengeführtes Planungs- und Kuratierungsunternehmen, das die Brüder selbst leiten, steht Ehrlichkeit an erster Stelle. Wir behandeln jeden Gast wie Familie und kümmern uns persönlich um jedes Detail Ihrer Reise.",
    about_join_title: "Machen Sie mit",
    about_join_body: "Kommen Sie zu Brother Sharm Tours und lassen Sie sich Sharm El-Sheikh so zeigen, wie man es erleben sollte!",

