    // Added by scripts/i18n-inject.mjs
    about_heading: "Chi siamo",
    about_welcome_title: "Benvenuti in Brother Sharm Tours",
    about_intro: "Benvenuti in Brother Sharm Tours, la vostra porta d'accesso alla bellezza mozzafiato e alle avventure emozionanti di Sharm El-Sheikh.",
    about_who_title: "Chi siamo",
    about_who_body: "Siamo due fratelli che chiamano con orgoglio Sharm El-Sheikh casa. Forti di un'esperienza diretta e di una profonda passione per il turismo e i viaggi che risale al 2009, il nostro percorso si fonda su anni di competenza. Ciò che ci ha davvero spinti a lanciare questa piattaforma è stato l'incoraggiamento costante di amici e clienti che hanno vissuto i nostri tour in prima persona. Amiamo profondamente i paesaggi del deserto, le acque cristalline del Mar Rosso e la vivace vita marina: la nostra missione è selezionare e farvi vivere le migliori esperienze di questo paradiso, collaborando con operatori locali di primo livello.",
    about_vision_title: "La nostra visione",
    about_vision_body: "Crediamo che ogni viaggiatore meriti un'esperienza personalizzata, sicura e indimenticabile. Ciò che ci distingue — e che ci sta più a cuore — sono la fiducia, la credibilità e i rapporti autentici, non la semplice vendita. Invece di tour standard, selezioniamo e organizziamo avventure su misura per creare ricordi indelebili: dai safari in quad nel deserto alle tranquille escursioni di snorkeling e immersioni.",
    about_why_title: "Perché viaggiare con noi?",
    about_local_title: "Esperienza locale",
