    about_welcome_title: "Witamy w Brother Sharm Tours",
    about_intro: "Witamy w Brother Sharm Tours — Twojej bramie do zapierającego dech piękna i ekscytujących przygód Sharm El-Sheikh.",
    about_who_title: "Kim jesteśmy",
    about_who_body: "Jesteśmy dwoma braćmi, dla których Sharm El-Sheikh jest domem. Praktyczne doświadczenie i głęboka pasja do turystyki sięgająca 2009 roku sprawiają, że nasza droga opiera się na latach wiedzy. Do stworzenia tej platformy zainspirowało nas nieustanne wsparcie przyjaciół i klientów, którzy osobiście poznali nasze wycieczki. Kochamy pustynne krajobrazy, krystalicznie czyste wody Morza Czerwonego i tętniące życiem rafy. Naszą misją jest wybierać dla Ciebie najlepsze doświadczenia tego raju i łączyć Cię z nimi, współpracując z najlepszymi lokalnymi operatorami.",
    about_vision_title: "Nasza wizja",
    about_vision_body: "Wierzymy, że każdy podróżny zasługuje na spersonalizowane, bezpieczne i niezapomniane przeżycie. Wyróżnia nas — i najbardziej nam zależy — na zaufaniu, wiarygodności i prawdziwych relacjach, a nie na samej sprzedaży. Zamiast standardowych wycieczek starannie dobieramy i organizujemy przygody tworzące wspomnienia na całe życie — od emocjonujących safari quadami po spokojne wyprawy ze snorkelingiem i nurkowaniem.",
    about_why_title: "Dlaczego warto z nami podróżować?",
    about_local_title: "Lokalna wiedza",
    about_local_body: "Znamy każde ukryte miejsce, najlepszą trasę i najciekawsze punkty w Sharm — dzięki doświadczeniu od 2009 roku poprowadzimy Cię właściwie.",
    about_safety_title: "Bezpieczeństwo przede wszystkim",
    about_safety_body: "Starannie współpracujemy z najbardziej zaufanymi, certyfikowanymi operatorami w Sharm, aby sprzęt, łodzie i pojazdy spełniały najwyższe standardy bezpieczeństwa — dla Twojego pełnego spokoju.",
    about_care_title: "Indywidualna opieka i wiarygodność",
    about_care_body: "Jako rodzinna firma planująca i dobierająca atrakcje, prowadzona bezpośrednio przez braci, stawiamy na uczciwość i traktujemy każdego gościa jak rodzinę, dbając osobiście o każdy szczegół podróży.",
