    about_welcome_title: "Добро пожаловать в Brother Sharm Tours",
    about_intro: "Добро пожаловать в Brother Sharm Tours — ваш путь к захватывающей красоте и ярким приключениям Шарм-эль-Шейха.",
    about_who_title: "Кто мы",
    about_who_body: "Мы — два брата, для которых Шарм-эль-Шейх — дом. Практический опыт и глубокая любовь к туризму с 2009 года — основа нашего пути. Создать эту платформу нас вдохновила постоянная поддержка друзей и клиентов, лично побывавших на наших экскурсиях. Мы влюблены в пустынные пейзажи, кристальные воды Красного моря и богатый подводный мир. Наша миссия — отобрать лучшее, что есть в этом раю, и открыть это вам, работая с ведущими местными операторами.",
    about_vision_title: "Наше видение",
    about_vision_body: "Мы верим, что каждый путешественник заслуживает индивидуального, безопасного и незабываемого опыта. Нас отличает — и для нас важнее всего — доверие, репутация и настоящие отношения, а не просто продажа. Вместо стандартных туров мы сами отбираем и организуем приключения, создающие воспоминания на всю жизнь: от захватывающих сафари на квадроциклах до спокойного снорклинга и дайвинга.",
