    about_safety_title: "Безопасность прежде всего",
    about_safety_body: "Мы тщательно выбираем самых надёжных сертифицированных операторов Шарма, чтобы снаряжение, суда и транспорт отвечали высшим стандартам безопасности — ради вашего спокойствия.",
    about_care_title: "Персональный подход и репутация",
