    // Added by scripts/i18n-inject.mjs
    about_heading: "À propos",
    about_welcome_title: "Bienvenue chez Brother Sharm Tours",
    about_intro: "Bienvenue chez Brother Sharm Tours, votre porte d'entrée vers la beauté à couper le souffle et les aventures palpitantes de Charm el-Cheikh.",
    about_who_title: "Qui sommes-nous",
    about_who_body: "Nous sommes deux frères qui appellent fièrement Charm el-Cheikh leur maison. Forts d'une expérience de terrain et d'une passion profonde pour le tourisme et le voyage depuis 2009, notre parcours repose sur des années d'expertise. Ce qui nous a vraiment poussés à lancer cette plateforme, ce sont les encouragements constants de nos amis et de nos clients qui ont vécu nos excursions. Nous aimons profondément les paysages du désert, les eaux cristallines de la mer Rouge et la vie marine foisonnante : notre mission est de sélectionner pour vous les meilleures expériences de ce paradis, en collaborant avec des opérateurs locaux de premier plan.",
    about_vision_title: "Notre vision",
    about_vision_body: "Nous croyons que chaque voyageur mérite une expérience personnalisée, sûre et inoubliable. Ce qui nous distingue — et ce qui compte le plus pour nous — c'est la confiance, la crédibilité et les relations authentiques, pas la simple vente. Plutôt que des circuits standards, nous sélectionnons et organisons des aventures sur mesure qui créent des souvenirs pour la vie : des safaris en quad dans le désert aux paisibles sorties snorkeling et plongée.",
    about_why_title: "Pourquoi voyager avec nous ?",
    about_local_title: "Expertise locale",
    about_local_body: "Nous connaissons chaque trésor caché, le meilleur itinéraire et les meilleurs spots de Charm — forts de notre expérience depuis 2009 pour bien vous guider.",
    about_safety_title: "La sécurité d'abord",
    about_safety_body: "Nous nous associons avec soin aux opérateurs les plus fiables et certifiés de Charm, afin que équipements, bateaux et véhicules répondent aux normes de sécurité les plus strictes, pour votre tranquillité totale.",
    about_care_title: "Attention personnalisée et crédibilité",
    about_care_body: "En tant qu'entreprise familiale de planification et de sélection dirigée directement par les frères, nous privilégions l'honnêteté et traitons chaque client comme un proche, avec une attention personnelle à chaque détail de votre voyage.",
    about_join_title: "Rejoignez-nous",
    about_join_body: "Rejoignez Brother Sharm Tours et laissez-nous vous faire découvrir Charm el-Cheikh comme il se doit !",

