    about_who_title: "Cine suntem",
    about_who_body: "Suntem doi frați care numesc cu mândrie Sharm El-Sheikh acasă. Cu experiență practică și o pasiune profundă pentru turism încă din 2009, drumul nostru se bazează pe ani de expertiză. Ceea ce ne-a inspirat cu adevărat să lansăm această platformă a fost încurajarea continuă a prietenilor și clienților care ne-au trăit tururile. Iubim peisajele deșertului, apele cristaline ale Mării Roșii și viața marină vibrantă, iar misiunea noastră este să selectăm și să vă conectăm cu cele mai bune experiențe ale acestui paradis, colaborând cu operatori locali de top.",
    about_vision_title: "Viziunea noastră",
    about_vision_body: "Credem că fiecare călător merită o experiență personalizată, sigură și de neuitat. Ceea ce ne diferențiază — și ne pasă cel mai mult — sunt încrederea, credibilitatea și relațiile autentice, nu simpla vânzare. În loc de tururi standard, selectăm și organizăm aventuri croite pentru amintiri de o viață — de la safari cu ATV-uri în deșert la excursii liniștite de snorkeling și scufundări.",
    about_why_title: "De ce să călătorești cu noi?",
