    about_local_body: "Cunoaștem fiecare colț ascuns, cea mai bună rută și cele mai bune locuri din Sharm, susținuți de experiența noastră din 2009 pentru a vă îndruma corect.",
    about_safety_title: "Siguranța pe primul loc",
    about_safety_body: "Colaborăm atent cu cei mai de încredere operatori certificați din Sharm, pentru ca echipamentele, ambarcațiunile și vehiculele să respecte cele mai înalte standarde de siguranță, pentru liniștea voastră deplină.",
