    // Added by scripts/i18n-inject.mjs
    about_heading: "Over ons",
    about_welcome_title: "Welkom bij Brother Sharm Tours",
    about_intro: "Welkom bij Brother Sharm Tours, uw toegangspoort tot de adembenemende schoonheid en spannende avonturen van Sharm El-Sheikh.",
    about_who_title: "Wie wij zijn",
    about_who_body: "Wij zijn twee broers die Sharm El-Sheikh met trots thuis noemen. Met praktijkervaring en een diepe passie voor toerisme sinds 2009 is onze weg gebouwd op jarenlange expertise. Wat ons echt inspireerde om dit platform te starten, was de voortdurende aanmoediging van vrienden en klanten die onze tours zelf meemaakten. We houden van de woestijnlandschappen, het kristalheldere water van de Rode Zee en het bruisende onderwaterleven. Onze missie: de allerbeste ervaringen van dit paradijs selecteren en u ermee verbinden, in samenwerking met eersteklas lokale operators.",
    about_vision_title: "Onze visie",
    about_vision_body: "Wij geloven dat elke reiziger een persoonlijke, veilige en onvergetelijke ervaring verdient. Wat ons onderscheidt — en wat ons het meest aan het hart gaat — is vertrouwen, geloofwaardigheid en echte relaties, niet zomaar een verkoop. In plaats van standaardtours kiezen en organiseren wij avonturen op maat die herinneringen voor het leven maken — van spannende quadsafari's in de woestijn tot rustige snorkel- en duikexcursies.",
    about_why_title: "Waarom met ons op reis?",
    about_local_title: "Lokale expertise",
    about_local_body: "Wij kennen elk verborgen pareltje, de beste route en de topplekken in Sharm — met onze ervaring sinds 2009 wijzen we u de juiste weg.",
    about_safety_title: "Veiligheid voorop",
    about_safety_body: "Wij werken zorgvuldig samen met de meest betrouwbare, gecertificeerde operators in Sharm, zodat uitrusting, boten en voertuigen voldoen aan de hoogste veiligheidsnormen — voor uw volledige gemoedsrust.",
    about_care_title: "Persoonlijke zorg & geloofwaardigheid",
    about_care_body: "Als familiebedrijf voor planning en curatie, rechtstreeks geleid door de broers, stellen wij eerlijkheid voorop en behandelen we elke gast als familie, met persoonlijke aandacht voor elk detail van uw reis.",
    about_join_title: "Doe met ons mee",
    about_join_body: "Sluit u aan bij Brother Sharm Tours en laat ons u Sharm El-Sheikh laten zien zoals het bedoeld is!",

